// Blink: the L LED on for 1 s, off for 1 s
void setup() {
  pinMode(LED_BUILTIN, OUTPUT);   // pin 13 = the L LED
}

void loop() {
  digitalWrite(LED_BUILTIN, HIGH);
  delay(1000);                    // blocks: nothing else runs for 1 s
  digitalWrite(LED_BUILTIN, LOW);
  delay(1000);
}

// A fade on pin 13, which has no PWM
void setup() {
  pinMode(13, OUTPUT);
}

void loop() {
  for (int v = 0; v < 256; v++) {
    analogWrite(13, v);   // pin 13 has no PWM timer:
    delay(8);             // 0-127 writes LOW, 128-255 writes HIGH
  }                       // fade on a ~ pin: 3, 5, 6, 9, 10 or 11
}

// Blink without delay(): toggle every 200 ms by the clock
unsigned long last = 0;
bool lit = false;

void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
}

void loop() {
  unsigned long now = millis();
  if (now - last >= 200) {        // non-blocking: are 200 ms up yet?
    last = now;
    lit = !lit;
    digitalWrite(LED_BUILTIN, lit ? HIGH : LOW);
  }
  // loop() stays free to read sensors, buttons and serial
}

// Serial hello: one line a second over USB
int n = 0;                 // int is 16 bits on the Uno: after 32767 comes -32768

void setup() {
  Serial.begin(9600);      // the serial monitor must use 9600 baud too
  Serial.println("Uno ready");
}

void loop() {
  Serial.print("hello, robot #");
  Serial.println(n++);
  delay(1000);
}
